input.command:
cd /tmp/probe && ./batch.sh lists/irr-lg-ix-ma-eau.txt > data/_ix.tsv 2>&1 && ./batch.sh lists/irr-lg-misc.txt > data/_misc.tsv 2>&1; cat data/_ix.tsv data/_misc.tsv >> data/irr-latin-greek.tsv
reg() { awk -F'\t' '{w=$1;p=$2; if (w ~ /(s|ch|sh)$/) r=w"es"; else if (w ~ /es$/) r=w; else if (w ~ /[^aeiou]y$/) {r=substr(w,1,length(w)-1)"ies"} else r=w"s"; if (p!=r) print}' "$1" | sort; }
echo "== IX/MA/EAU non-regular =="; reg data/_ix.tsv; echo; echo "== MISC non-regular =="; reg data/_misc.tsv

cd /tmp/probe && ./batch.sh lists/irr-lg-rev.txt > data/_rev.tsv 2>&1 && ./batch.sh lists/irr-lg-wide1.txt > data/_w1.tsv 2>&1; cat data/_rev.tsv data/_w1.tsv >> data/irr-latin-greek.tsv; wc -l data/irr-latin-greek.tsv
cat > /tmp/probe/reg.awk <<'EOF'
BEGIN{FS="\t"}
{w=tolower($1);p=$2;
 if (w ~ /es$/) r=w;
 else if (w ~ /(s|ch|sh)$/) r=w"es";
 else if (w ~ /[^aeiou]y$/) r=substr(w,1,length(w)-1)"ies";
 else r=w"s";
 if (p!=r) print $1"\t"p}
EOF
echo "== REV non-regular =="; awk -f /tmp/probe/reg.awk data/_rev.tsv | sort -u; echo; echo "== WIDE1 non-regular =="; awk -f /tmp/probe/reg.awk data/_w1.tsv | sort -u
